import { MakeLogicType, connect, kea, key, path, props, selectors } from 'kea'

import { insightDataLogic } from 'scenes/insights/insightDataLogic'
import { insightVizDataLogic } from 'scenes/insights/insightVizDataLogic'
import { keyForInsightLogicProps } from 'scenes/insights/sharedUtils'

import { InsightLogicProps } from '~/types'

import type { DateRange, Node } from '../../../queries/schema/schema-general'
import { dataRetentionBannerLogic } from './dataRetentionBannerLogic'
import { exceedsRetention } from './exceedsRetention'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightRetentionBannerLogicValues {
    retentionMonths: number | null // dataRetentionBannerLogic
    warningEligible: boolean // dataRetentionBannerLogic
    insightData: Record<string, any> // insightDataLogic
    query: Node | null // insightDataLogic
    dateRange: DateRange | null | undefined // insightVizDataLogic
    rangeExceedsRetention: boolean
    shouldShowBanner: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface insightRetentionBannerLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        rangeExceedsRetention: (
            dateRange: DateRange | null | undefined,
            insightData: Record<string, any>,
            retentionMonths: number | null,
            query: Node<Record<string, any>> | null
        ) => boolean
        shouldShowBanner: (warningEligible: boolean, rangeExceedsRetention: boolean) => boolean
    }
}

export type insightRetentionBannerLogicType = MakeLogicType<
    insightRetentionBannerLogicValues,
    {},
    InsightLogicProps,
    insightRetentionBannerLogicMeta
>

// Per-insight half of the retention warning: does this insight's range reach past the team's retention window?
// The rule itself lives in exceedsRetention so the dashboard-level banner answers the question identically.
export const insightRetentionBannerLogic = kea<insightRetentionBannerLogicType>([
    props({} as InsightLogicProps),
    key(keyForInsightLogicProps('new')),
    path((key) => ['scenes', 'insights', 'dataRetention', 'insightRetentionBannerLogic', key]),
    connect((props: InsightLogicProps) => ({
        values: [
            dataRetentionBannerLogic,
            ['warningEligible', 'retentionMonths'],
            insightDataLogic(props),
            ['insightData', 'query'],
            insightVizDataLogic(props),
            ['dateRange'],
        ],
    })),
    selectors({
        rangeExceedsRetention: [
            (s) => [s.dateRange, s.insightData, s.retentionMonths, s.query],
            (
                dateRange: null | import('../../../queries/schema').DateRange | undefined,
                insightData: Record<string, any>,
                retentionMonths: number | null,
                query: null | import('../../../queries/schema').Node
            ): boolean =>
                exceedsRetention({
                    query,
                    // The live editor range wins over whatever the saved query declares.
                    dateFromOverride: dateRange?.date_from,
                    resolvedDateFrom: insightData?.resolved_date_range?.date_from,
                    retentionMonths,
                }),
        ],
        shouldShowBanner: [
            (s) => [s.warningEligible, s.rangeExceedsRetention],
            (warningEligible: boolean, rangeExceedsRetention: boolean): boolean =>
                warningEligible && rangeExceedsRetention,
        ],
    }),
])
